<?php declare(strict_types=1); namespace Tests;
use App\Core\Database; use App\Repositories\{UserRepository,UserMediaRepository,UserSeriesProgressRepository}; use App\Integrations\Tmdb\TmdbMediaDetails; use PHPUnit\Framework\TestCase;
final class UserSeriesProgressRepositoryDatabaseTest extends TestCase {private Database$db;private UserSeriesProgressRepository$p;private UserRepository$u;protected function setUp():void{$name=getenv('FLICKARY_TEST_DB_DATABASE');if(!is_string($name)||!str_ends_with($name,'_test'))self::markTestSkipped('Disposable Flickary database was not configured.');$this->db=new Database(['host'=>getenv('FLICKARY_TEST_DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('FLICKARY_TEST_DB_PORT')?:3306),'database'=>$name,'username'=>getenv('FLICKARY_TEST_DB_USERNAME')?:'','password'=>getenv('FLICKARY_TEST_DB_PASSWORD')?:'','charset'=>'utf8mb4']);$this->p=new UserSeriesProgressRepository($this->db);$this->u=new UserRepository($this->db);$this->clear();}protected function tearDown():void{if(isset($this->db))$this->clear();}
 public function testSchemaIdempotencyIsolationBulkAndCascade():void{$a=$this->u->create('progress.a',null);$b=$this->u->create('progress.b',null);$this->p->markWatched($a,'tmdb',1396,1,1);$this->p->markWatched($a,'tmdb',1396,1,1);$this->p->markWatched($b,'tmdb',1396,1,1);self::assertSame([1],$this->p->watchedEpisodeNumbersForSeason($a,'tmdb',1396,1));$this->p->markSeasonWatched($a,'tmdb',1396,1,[1,2,3]);self::assertSame([1,2,3],$this->p->watchedEpisodeNumbersForSeason($a,'tmdb',1396,1));self::assertSame([1=>3],$this->p->countsBySeason($a,'tmdb',1396));self::assertSame(3,$this->p->countForSeries($a,'tmdb',1396));$this->p->unmarkWatched($a,'tmdb',1396,1,2);self::assertSame([1,3],$this->p->watchedEpisodeNumbersForSeason($a,'tmdb',1396,1));$this->p->clearSeason($a,'tmdb',1396,1);self::assertSame([],$this->p->watchedEpisodeNumbersForSeason($a,'tmdb',1396,1));self::assertSame([1],$this->p->watchedEpisodeNumbersForSeason($b,'tmdb',1396,1));$this->db->connection()->prepare('DELETE FROM users WHERE id=:id')->execute(['id'=>$b]);self::assertSame(0,$this->p->countForSeries($b,'tmdb',1396));}
 public function testProgressSurvivesRemovingAndReaddingUserMedia():void{$id=$this->u->create('progress.list',null);$m=new UserMediaRepository($this->db);$d=new TmdbMediaDetails('tmdb','series',1396,'Breaking Bad','Breaking Bad',null,null,'2008-01-20',2008,null,null,[],null,null,null,'en',false,null,null,5,62,null,false);$m->create($id,$d,'watching');$this->p->markSeasonWatched($id,'tmdb',1396,1,[1,2]);$m->delete($id,'tmdb','series',1396);self::assertSame([1,2],$this->p->watchedEpisodeNumbersForSeason($id,'tmdb',1396,1));$m->create($id,$d,'paused');self::assertSame([1,2],$this->p->watchedEpisodeNumbersForSeason($id,'tmdb',1396,1));}
 private function clear():void{$p=$this->db->connection();$p->exec('DELETE FROM user_series_episode_progress');$p->exec('DELETE FROM user_media');$p->exec('DELETE FROM user_external_identities');$p->exec('DELETE FROM user_profiles');$p->exec('DELETE FROM users');}}
